            for method in methods:
                if method(candidate):
                    return self
        return self


class LegacyModuleUtilLocator(ModuleUtilLocatorBase):
    prefix_length = 2

    def __init__(self, fq_name_parts, is_ambiguous=False, mu_paths=None, child_is_redirected=False):
        super(LegacyModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous, child_is_redirected)
        self.mu_paths = mu_paths if mu_paths is not None else [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)] + [_MODULE_UTILS_PATH]

    def _local(self, parts):
        if parts[:3] == ('ansible', 'module_utils', 'six'):
            parts = parts[:3]
        rel = parts[2:]
        if not rel:
            return False
        try:
            info = ModuleInfo(rel[-1], [os.path.join(p, *rel[:-1]) for p in self.mu_paths])
        except (ImportError, OSError):
            return False
        if not info.pkg_dir and not info.py_src:
            raise AnsibleError('Could not find python source for imported module support code for %s' % '.'.join(parts))
        self._set_source(parts, info.get_source(), info.path, info.pkg_dir)
        return True

    def _redirect(self, parts):
        name = '.'.join(parts[2:])
        routing = _get_collection_metadata('ansible.builtin').get('plugin_routing', {}).get('module_utils', {})
        entry = routing.get(name, {})
        if not entry:
            return False
        target = _routing_target(entry, 'ansible.builtin', name)
        if target:
            self._set_redirect(parts, target)
            return True
        return False


class CollectionModuleUtilLocator(ModuleUtilLocatorBase):
    prefix_length = 5
    redirect_first = True

    def _metadata(self, parts):
        collection = '.'.join(parts[1:3])
        try:
            return _get_collection_metadata(collection)
        except ValueError as exc:
            raise AnsibleError(to_native(exc))

    def _redirect(self, parts):
        collection = '.'.join(parts[1:3])
        name = '.'.join(parts[5:])
        entry = self._metadata(parts).get('plugin_routing', {}).get('module_utils', {}).get(name, {})
        if not entry:
            return False
        target = _routing_target(entry, collection, name)
        if target:
            self._set_redirect(parts, target)
            return True
        return False

    def _local(self, parts):
        if len(parts) <= 5:
            return False
        collection_pkg = '.'.join(parts[:3])
        resource = os.path.join(*parts[3:])
        try:
            pkg_source = pkgutil.get_data(collection_pkg, resource + '/__init__.py')
            mod_source = None if pkg_source is not None else pkgutil.get_data(collection_pkg, resource + '.py')
        except (IOError, OSError, ImportError, ValueError):
            return False
        if pkg_source is None and mod_source is None:
            return False
        is_package = pkg_source is not None
        self._set_source(parts, pkg_source if is_package else mod_source,
                         resource + ('/__init__.py' if is_package else '.py'), is_package)
        return True


def _routing_target(entry, collection, name):
    tombstone = entry.get('tombstone')
    if tombstone:
        raise AnsibleError('%s: module_utils %s in collection %s was removed (removal_version=%s, removal_date=%s)' %
                           (tombstone.get('warning_text', tombstone.get('message', 'Removed')),
                            name, collection, tombstone.get('removal_version'), tombstone.get('removal_date')))
    target = entry.get('redirect')
    if not target:
        return None
    deprecation = entry.get('deprecation')
    if deprecation:
        display.deprecated(deprecation.get('warning_text', 'module_utils %s is deprecated' % name),
                           version=deprecation.get('removal_version'), date=deprecation.get('removal_date'),
                           collection_name=collection)
    parts = tuple(target.split('.'))
    if parts[0] "'!= '"'ansible_collections' and parts[0] "'!= '"'ansible':
        parts = ('ansible_collections',) + parts[:2] + ('plugins', 'module_utils') + parts[2:]
    return parts


def recursive_finder(name, module_fqn, data, py_module_names, py_module_cache, zf):
    \"\"\"Collect module_utils and their imports with a work queue.\"\"\"
    paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)] + [_MODULE_UTILS_PATH]
    pending = deque([(name, module_fqn, data, False)])
    queued = set()
    written = set(zf.namelist())

    def add(parts, source, path, is_package=False, scan=True):
        key = parts + (('__init__',) if is_package else ())
        output = '/'.join(key) + '.py'
        if key in py_module_names or output in written:
            return
        py_module_names.add(key)
        zf.writestr(output, source)
        written.add(output)
        display.vvvvv('Using module_utils file %s' % to_text(path, errors='surrogate_or_strict'))
        if scan:
            pending.append((parts[-1], '.'.join(parts), source, is_package))

    def parents(parts):
        for end in range(1, len(parts)):
            parent = parts[:end]
            key = parent + ('__init__',)
            if key in py_module_names or '/'.join(key) + '.py' in written:
                continue
            if parts[0] == 'ansible' and end <= 2:
                continue
            locator = None
            if parts[0] == 'ansible_collections' and end > 5:
                locator = CollectionModuleUtilLocator(parent).resolve()
            elif parts[0] == 'ansible' and end > 2:
                locator = LegacyModuleUtilLocator(parent, mu_paths=paths).resolve()
            if locator and locator.found and locator.is_package:
                add(parent, locator.source, locator.path, True)
            else:
                add(parent, b'', '/'.join(parent) + '/__init__.py', True, False)

    # The wrapper imports basic unconditionally.
    basic = LegacyModuleUtilLocator(('ansible', 'module_utils', 'basic'), mu_paths=paths).resolve()
    if basic.found:
        add(basic.name_parts, basic.source, basic.path, basic.is_package)

    while pending:
        current_name, current_fqn, source, is_package = pending.popleft()
        try:
            tree = compile(source, '<unknown>', 'exec', ast.PyCF_ONLY_AST)
        except (SyntaxError, IndentationError) as exc:
            raise AnsibleError('Unable to import %s due to %s' % (current_name, exc.msg))
        finder = ModuleDepFinder(current_fqn, is_package=is_package)
        finder.visit(tree)
        for parts in sorted(finder.submodules):
            if parts == ('_six',):
                continue
            if parts[:3] == ('ansible', 'module_utils', 'six'):
                parts = parts[:3]
            if parts[:2] == ('ansible', 'module_utils'):
                locator = LegacyModuleUtilLocator(parts, is_ambiguous=True, mu_paths=paths).resolve()
            elif parts[:5] == ('ansible_collections',) + parts[1:3] + ('plugins', 'module_utils'):
                locator = CollectionModuleUtilLocator(parts, is_ambiguous=True).resolve()
            else:
                continue
            if not locator.found:
                raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                                   (current_fqn, ', '.join(locator.candidate_names_joined())))
            parents(locator.name_parts)
            add(locator.name_parts, locator.source, locator.path, locator.is_package)
            if locator.redirected and locator.redirect_target not in queued:
                queued.add(locator.redirect_target)
                target = locator.redirect_target
                if target[:2] == ('ansible', 'module_utils'):
                    resolved = LegacyModuleUtilLocator(target, mu_paths=paths).resolve()
                else:
                    resolved = CollectionModuleUtilLocator(target).resolve()
                if not resolved.found:
                    raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                                       (current_fqn, '.'.join(target)))
                parents(resolved.name_parts)
                add(resolved.name_parts, resolved.source, resolved.path, resolved.is_package)
    py_module_cache.clear()
